pub fn dt_named_p(name: Str, ds: Dts) -> bool {
    any_p(lambda1(move |d: &'static Dt| {
        let tagcase_ = d;
        match *tagcase_ {
            Dt::Dt(n, ps, vs) => {
                string_eq_p(n, name)
            }
        }
    }), ds)
}

/// A datatype, its parameters and variants, as a list of one, or none.
pub fn find_family(mut name: Str, mut ds: Dts) -> List<&'static Dt> {
    loop {
        if null_p(ds) {
            return nil::<&'static Dt>();
        } else if {
            let tagcase_ = car(ds);
            match *tagcase_ {
                Dt::Dt(n, ps, vs) => {
                    string_eq_p(n, name)
                }
            }
        } {
            return kayak_rt::heap_cons(car(ds), kayak_rt::nil());
        } else {
            ds = cdr(ds);
            continue;
        }
    }
}

/// A type abbreviation, its parameters and what it stands for, as a list
/// of one, or none.
pub fn find_alias(mut name: Str, mut als: Aliases) -> List<&'static Alias> {
    loop {
        if null_p(als) {
            return nil::<&'static Alias>();
        } else {
            let tagcase_ = car(als);
            match *tagcase_ {
                Alias::Alias(n, ps, t) => {
                    if string_eq_p(n, name) {
                        return kayak_rt::heap_cons(car(als), kayak_rt::nil());
                    } else {
                        als = cdr(als);
                        continue;
                    }
                }
            }
        }
    }
}

/// The type abbreviations being expanded, which `tvars` carries, marked,
/// so that one that mentions itself is found.
pub fn expanding(mut tvars: Strings) -> Strings {
    loop {
        if null_p(tvars) {
            return nil::<Str>();
        } else if (i64_gt(string_length_i64(car(tvars)), 0i64) && char_eq_p(string_ref_i64(car(tvars), 0i64), '%')) {
            return kayak_rt::heap_cons(car(tvars), expanding(cdr(tvars)));
        } else {
            tvars = cdr(tvars);
            continue;
        }
    }
}

/// The innermost binding of `name`, as a list of one, or none.
pub fn find_bind(mut name: Str, mut bs: Binds) -> Binds {
    loop {
        if null_p(bs) {
            return nil::<&'static Bind>();
        } else {
            let tagcase_ = car(bs);
            match *tagcase_ {
                Bind::Bind(n, sc, wher) => {
                    if string_eq_p(n, name) {
                        return kayak_rt::heap_cons(car(bs), kayak_rt::nil());
                    } else {
                        bs = cdr(bs);
                        continue;
                    }
                }
            }
        }
    }
}

/// A generative type's conversion, the global or item `name`: not a local
/// that hides it.
pub fn conversion_bind(mut name: Str, mut bs: Binds) -> Binds {
    loop {
        if null_p(bs) {
            return nil::<&'static Bind>();
        } else if {
            let tagcase_ = car(bs);
            match *tagcase_ {
                Bind::Bind(n, sc, w) => {
                    (string_eq_p(n, name) && (string_eq_p(w, str_lit("global")) || string_eq_p(w, str_lit("item"))))
                }
            }
        } {
            return the::<Binds>(kayak_rt::heap_cons(car(bs), kayak_rt::nil()));
        } else {
            bs = cdr(bs);
            continue;
        }
    }
}

pub fn char_lower_p(c: char) -> bool {
    has_char_in_p(str_lit("abcdefghijklmnopqrstuvwxyz"), c)
}

pub fn same_at_p(s: Str, part: Str, at: i64, i: i64, n: i64) -> bool {
    (i64_eq(i, n) || (char_eq_p(string_ref_i64(s, i64_plus(at, i)), string_ref_i64(part, i)) && same_at_p(s, part, at, i64_plus(i, 1i64), n)))
}

pub fn has_from_p(s: Str, part: Str, at: i64) -> bool {
    (not(i64_lt(i64_minus(string_length_i64(s), at), string_length_i64(part))) && (same_at_p(s, part, at, 0i64, string_length_i64(part)) || has_from_p(s, part, i64_plus(at, 1i64))))
}

/// Whether `part` is in `s`: compared in place, making nothing.
pub fn string_has_p(s: Str, part: Str) -> bool {
    has_from_p(s, part, 0i64)
}

/// Whether `n` is a Rust keyword no raw identifier may be, `self`, `super`,
/// `crate`, or one as a type's name (`Self`): KFX names none so. The
/// others are Rust's `r#loop` (C41).
pub fn rust_keyword_clash_p(n: Str) -> bool {
    (string_member_p(n, kayak_rt::heap_cons(str_lit("self"), kayak_rt::heap_cons(str_lit("super"), kayak_rt::heap_cons(str_lit("crate"), kayak_rt::nil())))) || string_eq_p(camel(n), str_lit("Self")))
}

/// The types Rust or kayak-rt has that the emitter writes: no KFX type and
/// no type variable is named so, camel-cased, which would hide it.
pub fn rust_type_names() -> Strings {
    kayak_rt::heap_cons(str_lit("Str"), kayak_rt::heap_cons(str_lit("List"), kayak_rt::heap_cons(str_lit("Cons"), kayak_rt::heap_cons(str_lit("Int"), kayak_rt::heap_cons(str_lit("Tag"), kayak_rt::heap_cons(str_lit("Unwind"), kayak_rt::heap_cons(str_lit("Ref"), kayak_rt::heap_cons(str_lit("FlatArray"), kayak_rt::heap_cons(str_lit("Knot"), kayak_rt::heap_cons(str_lit("Show"), kayak_rt::heap_cons(str_lit("OnceCell"), kayak_rt::heap_cons(str_lit("Fn"), kayak_rt::heap_cons(str_lit("Result"), kayak_rt::heap_cons(str_lit("Ok"), kayak_rt::heap_cons(str_lit("Err"), kayak_rt::heap_cons(str_lit("String"), kayak_rt::heap_cons(str_lit("Copy"), kayak_rt::heap_cons(str_lit("Clone"), kayak_rt::heap_cons(str_lit("Self"), kayak_rt::heap_cons(str_lit("Module"), kayak_rt::heap_cons(str_lit("Void"), kayak_rt::heap_cons(str_lit("Bloblet"), kayak_rt::heap_cons(str_lit("BlobRef"), kayak_rt::heap_cons(str_lit("Arena"), kayak_rt::heap_cons(str_lit("Holds"), kayak_rt::heap_cons(str_lit("ListAt"), kayak_rt::heap_cons(str_lit("RefAt"), kayak_rt::heap_cons(str_lit("TBloblet"), kayak_rt::heap_cons(str_lit("FlatArr"), kayak_rt::heap_cons(str_lit("Flat"), kayak_rt::heap_cons(str_lit("Owner"), kayak_rt::heap_cons(str_lit("Cell"), kayak_rt::heap_cons(str_lit("Default"), kayak_rt::heap_cons(str_lit("Procedure"), kayak_rt::nil()))))))))))))))))))))))))))))))))))
}

/// Whether `n` may be a KFX name (C27): a lower-case letter or an operator's
/// character first, then those, digits and `-`; no `--` (the emitter's
/// `__`); and none whose Rust name kayak-rt or the emitter writes.
pub fn kfx_name_p(n: Str) -> bool {
    let cs = string_chars(n);
    (not(null_p(cs)) && not(rust_keyword_clash_p(n)) && (char_lower_p(car(cs)) || has_char_in_p(str_lit("?!<>=+*/%-"), car(cs))) && not(any_p(lambda1(move |c: char| {
        not((char_lower_p(c) || char_numeric_p(c) || has_char_in_p(str_lit("?!<>=+*/%-"), c)))
    }), cs)) && not(string_has_p(n, str_lit("--"))) && not(string_member_p(mangle(n), kayak_rt::heap_cons(str_lit("str_lit"), kayak_rt::heap_cons(str_lit("int_lit"), kayak_rt::heap_cons(str_lit("int_text"), kayak_rt::heap_cons(str_lit("unreachable_unwind"), kayak_rt::heap_cons(str_lit("kfx_toplevel"), kayak_rt::heap_cons(str_lit("once"), kayak_rt::heap_cons(str_lit("alloc"), kayak_rt::heap_cons(str_lit("the"), kayak_rt::heap_cons(str_lit("unwind"), kayak_rt::heap_cons(str_lit("knot"), kayak_rt::heap_cons(str_lit("lambda0"), kayak_rt::heap_cons(str_lit("lambda1"), kayak_rt::heap_cons(str_lit("lambda2"), kayak_rt::heap_cons(str_lit("lambda3"), kayak_rt::heap_cons(str_lit("lambda4"), kayak_rt::heap_cons(str_lit("leak_string"), kayak_rt::heap_cons(str_lit("with_big_stack"), kayak_rt::heap_cons(str_lit("fail"), kayak_rt::heap_cons(str_lit("make_continuation_prompt_tag"), kayak_rt::heap_cons(str_lit("nil"), kayak_rt::heap_cons(str_lit("cons"), kayak_rt::nil()))))))))))))))))))))))))
}

// A knot through the store (FX-26's `no_knot`): a procedure kept in
// storage at a region, whose latent effect reads that region and does not
// say `spin`, could be fetched from there by a procedure fetched from
// there, a loop with no recursive call, which only its type shows. The
// regions a type keeps things in: a `ref`'s, a list's not `acyclic`; a
// datatype keeps where its fields do; what a generative type is given, KFX
// takes as kept everywhere, more cautious than FX-26. `res` resolves an
// effect's inference variables.
pub fn region_name_of(r: &'static Ty) -> Str {
    let tagcase_ = r;
    match *tagcase_ {
        Ty::TyVar(n) => {
            n
        }
        Ty::TyRconst(n) => {
            n
        }
        Ty::TyMeta(k) => {
            meta_name(k)
        }
        _ => {
            let other = tagcase_;
            str_lit("?")
        }
    }
}

pub fn reads_kept(atoms: Strings, kept: Strings, every: bool) -> Strings {
    if string_member_p(str_lit("spin"), atoms) {
        nil::<Str>()
    } else {
        concat(map(lambda1(move |x: Str| {
            if (has_prefix_p(x, str_lit("read:")) && (string_member_p(after_prefix(x, str_lit("read:")), kept) || (every && not(string_eq_p(after_prefix(x, str_lit("read:")), str_lit("acyclic")))))) {
                the::<Strings>(kayak_rt::heap_cons(after_prefix(x, str_lit("read:")), kayak_rt::nil()))
            } else {
                nil::<Str>()
            }
        }), atoms))
    }
}

/// The region of a knot `t` ties, kept in `kept` (everywhere, if
/// `every`); or none.
pub fn knot_in(mut v: &'static Cv, mut res: &'static dyn Fn(Str) -> Str, mut t: &'static Ty, mut kept: Strings, mut every: bool, mut seen: Strings) -> Strings {
    loop {
        let tagcase_ = t;
        match *tagcase_ {
            Ty::TyRef(a, r) => {
                (t, kept) = (a, kayak_rt::heap_cons(region_name_of(r), kept));
                continue;
            }
            Ty::TyList(a, r) => {
                (t, kept) = (a, if (string_eq_p(region_name_of(r), str_lit("acyclic")) || string_eq_p(region_name_of(r), str_lit("%fresh"))) {
                    kept
                } else {
                    kayak_rt::heap_cons(region_name_of(r), kept)
                });
                continue;
            }
            Ty::TyProc(es, ps, r) => {
                let found = reads_kept(map(res, es), kept, every);
                if null_p(found) {
                    return first_knot(v, res, kayak_rt::heap_cons(r, ps), nil::<Str>(), false, seen);
                } else {
                    return found;
                }
            }
            Ty::TyTag(a, h, d, r) => {
                return first_knot(v, res, kayak_rt::heap_cons(a, kayak_rt::heap_cons(h, kayak_rt::nil())), nil::<Str>(), false, seen);
            }
            Ty::TyShape(p, ls, ts) => {
                return first_knot(v, res, ts, kept, every, seen);
            }
            Ty::TyData(d, args) => {
                if string_member_p(d, seen) {
                    return nil::<Str>();
                } else {
                    let found = find_family(d, cv_dts(v));
                    if null_p(found) {
                        return nil::<Str>();
                    } else {
                        let tagcase_ = car(found);
                        match *tagcase_ {
                            Dt::Dt(n, ps, vs) => {
                                if null_p(vs) {
                                    let down = conversion_bind(string_append(str_lit("down-"), d), cv_binds(v));
                                    return first_knot(v, res, onto(if null_p(down) {
                                        nil::<&'static Ty>()
                                    } else {
                                        let tagcase_ = car(down);
                                        match *tagcase_ {
                                            Bind::Bind(n, sc, w) => {
                                                let tagcase_ = sc;
                                                match *tagcase_ {
                                                    Scheme::Scheme(tvars, t) => {
                                                        let tagcase_ = t;
                                                        match *tagcase_ {
                                                            Ty::TyProc(es, xs, r) => {
                                                                the::<Tys>(kayak_rt::heap_cons(substitute(ps, args, r), kayak_rt::nil()))
                                                            }
                                                            _ => {
                                                                let other = tagcase_;
                                                                nil::<&'static Ty>()
                                                            }
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                    }, args), kept, true, kayak_rt::heap_cons(d, seen));
                                } else {
                                    return first_knot(v, res, concat(map(lambda1(move |x: &'static Variant| {
                                        let tagcase_ = x;
                                        match *tagcase_ {
                                            Variant::Variant(tag, fs) => {
                                                map(lambda1(move |f: &'static Ty| {
                                                    substitute(ps, args, f)
                                                }), fs)
                                            }
                                        }
                                    }), vs)), kept, every, kayak_rt::heap_cons(d, seen));
                                }
                            }
                        }
                    }
                }
            }
            _ => {
                let other = tagcase_;
                return nil::<Str>();
            }
        }
    }
}

pub fn first_knot(mut v: &'static Cv, mut res: &'static dyn Fn(Str) -> Str, mut ts: Tys, mut kept: Strings, mut every: bool, mut seen: Strings) -> Strings {
    loop {
        if null_p(ts) {
            return nil::<Str>();
        } else {
            let found = knot_in(v, res, car(ts), kept, every, seen);
            if null_p(found) {
                ts = cdr(ts);
                continue;
            } else {
                return found;
            }
        }
    }
}

pub fn no_knot(v: &'static Cv, res: &'static dyn Fn(Str) -> Str, t: &'static Ty) -> &'static Ty {
    let found = knot_in(v, res, t, nil::<Str>(), false, nil::<Str>());
    if null_p(found) {
        t
    } else {
        match refuse(v, string_append(str_lit("a procedure kept in "), string_append(car(found), string_append(str_lit(" reads "), string_append(car(found), str_lit(", so it could reach itself: it must say spin")))))) {}
    }
}

// Flats (C31): what a blobref points to, raw bytes in a bloblet's suffix,
// laid out as C lays them out: a scalar at its size, a product's fields in
// order each at its alignment and the whole padded to the widest, an
// array's elements one after another. KFX's scalars are FX-26's but `f32`,
// which KFX has not yet.
pub fn run_together(xs: Strings) -> Str {
    if null_p(xs) {
        str_lit("")
    } else {
        string_append(car(xs), run_together(cdr(xs)))
    }
}

pub fn key_range(key: Str) -> i64 {
    if string_eq_p(key, str_lit("u8")) {
        256i64
    } else if string_eq_p(key, str_lit("u16")) {
        65536i64
    } else {
        4294967296i64
    }
}

pub fn key_width(k: &'static Ty) -> i64 {
    let tagcase_ = k;
    match *tagcase_ {
        Ty::TyRconst(n) => {
            if string_eq_p(n, str_lit("u8")) {
                1i64
            } else if string_eq_p(n, str_lit("u16")) {
                2i64
            } else {
                4i64
            }
        }
        _ => {
            let other = tagcase_;
            4i64
        }
    }
}

pub enum Fvar {
    Fvar(Str, &'static Ty),
}

pub fn fvar(f0: Str, f1: &'static Ty) -> &'static Fvar {
    kayak_rt::heap_alloc(Fvar::Fvar(f0, f1))
}

pub type Fvars = List<&'static Fvar>;

pub fn fvars_of(ts: Tys) -> Fvars {
    if (null_p(ts) || null_p(cdr(ts))) {
        nil::<&'static Fvar>()
    } else {
        kayak_rt::heap_cons(fvar({
            let tagcase_ = car(ts);
            match *tagcase_ {
                Ty::TyRconst(n) => {
                    n
                }
                _ => {
                    let other = tagcase_;
                    str_lit("")
                }
            }
        }, car(cdr(ts))), fvars_of(cdr(cdr(ts))))
    }
}

/// A keyed flat sum's variants, its type's arguments after the key.
pub fn flat_sum_variants(args: Tys) -> Fvars {
    fvars_of(cdr(args))
}

pub fn flat_p(t: &'static Ty) -> bool {
    let tagcase_ = t;
    match *tagcase_ {
        Ty::TyI64() => {
            true
        }
        Ty::TyF64() => {
            true
        }
        Ty::TyData(d, args) => {
            ((null_p(args) && (string_eq_p(d, str_lit("i32")) || string_eq_p(d, str_lit("u32")) || string_eq_p(d, str_lit("u64")) || string_eq_p(d, str_lit("f32")))) || (string_eq_p(d, str_lit("%flat-array")) && flat_p(car(args))) || string_eq_p(d, str_lit("%flat-sum")))
        }
        Ty::TyShape(p, ls, ts) => {
            (p && not(null_p(ts)) && not(any_p(lambda1(move |x: &'static Ty| {
                not(flat_p(x))
            }), ts)))
        }
        _ => {
            let other = tagcase_;
            false
        }
    }
}

/// Whether a type could hold a procedure: is one, a type variable, or
/// has one inside.
pub fn field_may_knot_p(mut t: &'static Ty) -> bool {
    loop {
        let tagcase_ = t;
        match *tagcase_ {
            Ty::TyProc(es, ps, r) => {
                return true;
            }
            Ty::TyVar(n) => {
                return true;
            }
            Ty::TyMeta(k) => {
                return true;
            }
            Ty::TyList(e, r) => {
                t = e;
                continue;
            }
            Ty::TyRef(e, r) => {
                t = e;
                continue;
            }
            Ty::TyFlat(e, r) => {
                t = e;
                continue;
            }
            Ty::TyTag(a, h, d, r) => {
                return true;
            }
            Ty::TyShape(p, ls, ts) => {
                return any_p(lambda1(move |x: &'static Ty| {
                    field_may_knot_p(x)
                }), ts);
            }
            Ty::TyData(d, args) => {
                return any_p(lambda1(move |x: &'static Ty| {
                    field_may_knot_p(x)
                }), args);
            }
            _ => {
                let other = tagcase_;
                return false;
            }
        }
    }
}

pub enum Layout {
    Layout(i64, i64),
}

pub fn layout(f0: i64, f1: i64) -> &'static Layout {
    kayak_rt::heap_alloc(Layout::Layout(f0, f1))
}

pub fn round_up(n: i64, a: i64) -> i64 {
    i64_star(i64_quotient(i64_plus(n, i64_minus(a, 1i64)), a), a)
}

/// A flat's size and alignment, in bytes.
pub fn flat_layout(t: &'static Ty) -> &'static Layout {
    let tagcase_ = t;
    match *tagcase_ {
        Ty::TyData(d, args) => {
            if string_eq_p(d, str_lit("%flat-array")) {
                let tagcase_ = flat_layout(car(args));
                match *tagcase_ {
                    Layout::Layout(size, align) => {
                        layout(i64_star(size, {
                            let tagcase_ = car(cdr(args));
                            match *tagcase_ {
                                Ty::TyRconst(n) => {
                                    i64_minus(0i64, digits_value(string_chars(n), 0i64, str_lit(""), 0i64))
                                }
                                _ => {
                                    let other = tagcase_;
                                    0i64
                                }
                            }
                        }), align)
                    }
                }
            } else if string_eq_p(d, str_lit("u64")) {
                layout(8i64, 8i64)
            } else if string_eq_p(d, str_lit("%flat-sum")) {
                let k = key_width(car(args));
                let vs = flat_sum_variants(args);
                let widest = any_layout(map(lambda1(move |f: &'static Fvar| {
                    let tagcase_ = f;
                    match *tagcase_ {
                        Fvar::Fvar(l, x) => {
                            x
                        }
                    }
                }), vs), 0i64, 1i64);
                let tagcase_ = widest;
                match *tagcase_ {
                    Layout::Layout(size, align) => {
                        let (at, whole) = (round_up(k, align), if i64_gt(align, k) {
                            align
                        } else {
                            k
                        });
                        layout(round_up(i64_plus(at, size), whole), whole)
                    }
                }
            } else {
                layout(4i64, 4i64)
            }
        }
        Ty::TyShape(p, ls, ts) => {
            let tagcase_ = fields_layout(ts, 0i64, 1i64);
            match *tagcase_ {
                Layout::Layout(end, align) => {
                    layout(round_up(end, align), align)
                }
            }
        }
        _ => {
            let other = tagcase_;
            layout(8i64, 8i64)
        }
    }
}

/// The widest of flats `ts` and their widest alignment: a sum's variant's room.
pub fn any_layout(mut ts: Tys, mut size: i64, mut align: i64) -> &'static Layout {
    loop {
        if null_p(ts) {
            return layout(size, align);
        } else {
            let tagcase_ = flat_layout(car(ts));
            match *tagcase_ {
                Layout::Layout(s, a) => {
                    (ts, size, align) = (cdr(ts), if i64_gt(s, size) {
                        s
                    } else {
                        size
                    }, if i64_gt(a, align) {
                        a
                    } else {
                        align
                    });
                    continue;
                }
            }
        }
    }
}

/// The end of fields `ts` laid out from `at`, and their widest alignment.
pub fn fields_layout(mut ts: Tys, mut at: i64, mut align: i64) -> &'static Layout {
    loop {
        if null_p(ts) {
            return layout(at, align);
        } else {
            let tagcase_ = flat_layout(car(ts));
            match *tagcase_ {
                Layout::Layout(size, a) => {
                    (ts, at, align) = (cdr(ts), i64_plus(round_up(at, a), size), if i64_gt(a, align) {
                        a
                    } else {
                        align
                    });
                    continue;
                }
            }
        }
    }
}

/// Where a keyed flat sum's variant begins: after its tag, at the widest
/// variant's alignment.
pub fn variant_offset(args: Tys) -> i64 {
    let tagcase_ = any_layout(map(lambda1(move |f: &'static Fvar| {
        let tagcase_ = f;
        match *tagcase_ {
            Fvar::Fvar(l, x) => {
                x
            }
        }
    }), flat_sum_variants(args)), 0i64, 1i64);
    match *tagcase_ {
        Layout::Layout(size, align) => {
            round_up(key_width(car(args)), align)
        }
    }
}

/// The offset of a flat product's field `l`.
pub fn field_offset(ls: Strings, ts: Tys, l: Str) -> i64 {
    let go__knot = knot::<&'static dyn Fn(Strings, Tys, i64) -> i64>();
    let go = lambda3(move |mut ls: Strings, mut ts: Tys, mut at: i64| {
        loop {
            let tagcase_ = flat_layout(car(ts));
            match *tagcase_ {
                Layout::Layout(size, a) => {
                    if string_eq_p(car(ls), l) {
                        return round_up(at, a);
                    } else {
                        (ls, ts, at) = (cdr(ls), cdr(ts), i64_plus(round_up(at, a), size));
                        continue;
                    }
                }
            }
        }
    });
    go__knot.set(go);
    go(ls, ts, 0i64)
}

/// A flat scalar's name, as its blobref's read and write are named; or ``.
pub fn scalar_name(t: &'static Ty) -> Str {
    let tagcase_ = t;
    match *tagcase_ {
        Ty::TyI64() => {
            str_lit("i64")
        }
        Ty::TyF64() => {
            str_lit("f64")
        }
        Ty::TyData(d, args) => {
            if null_p(args) {
                d
            } else {
                str_lit("")
            }
        }
        _ => {
            let other = tagcase_;
            str_lit("")
        }
    }
}

/// FX-26's fixed-width integers beside `i64` (`u8` and `i8` since Fixpt 17ac0c5), whose arithmetic wraps: a type
/// named so, as a datatype is, of no variants; in Rust, Rust's.
pub fn fixed_width_p(s: Str) -> bool {
    (string_eq_p(s, str_lit("i32")) || string_eq_p(s, str_lit("u32")) || string_eq_p(s, str_lit("u64")) || string_eq_p(s, str_lit("u8")) || string_eq_p(s, str_lit("i8")))
}

// Unions of shapes (C62; FX-26's, docs/fx26.md "Unions of shapes"): a
// value of any of its members, whose shapes at run time differ, so that a
// test tells them apart. A `(ty-data "%union" members)`, flattened, each
// member once; `false`, the type of `#f` alone, below `bool`, a
// `(ty-data "false" nil)`. Never Rust's (C57): the restriction pass's.
/// A member's shape at run time, or `` if it has none known.
pub fn shape_of(t: &'static Ty) -> Str {
    let tagcase_ = t;
    match *tagcase_ {
        Ty::TyI64() => {
            str_lit("int")
        }
        Ty::TyInt() => {
            str_lit("int")
        }
        Ty::TyNat() => {
            str_lit("int")
        }
        Ty::TyF64() => {
            str_lit("f64")
        }
        Ty::TyChar() => {
            str_lit("char")
        }
        Ty::TyBool() => {
            str_lit("bool")
        }
        Ty::TyString() => {
            str_lit("string")
        }
        Ty::TyUnit() => {
            str_lit("symbol")
        }
        Ty::TyList(e, r) => {
            str_lit("list")
        }
        Ty::TyProc(es, ps, r) => {
            str_lit("procedure")
        }
        Ty::TyRef(e, r) => {
            str_lit("box")
        }
        Ty::TyFlat(e, r) => {
            str_lit("bloblet")
        }
        Ty::TyShape(p, ls, ts) => {
            if p {
                str_lit("product")
            } else {
                str_lit("sum")
            }
        }
        Ty::TyData(d, args) => {
            if (string_eq_p(d, str_lit("i32")) || string_eq_p(d, str_lit("u32")) || string_eq_p(d, str_lit("u64")) || string_eq_p(d, str_lit("u8")) || string_eq_p(d, str_lit("i8"))) {
                str_lit("int")
            } else if string_eq_p(d, str_lit("f32")) {
                str_lit("f32")
            } else if string_eq_p(d, str_lit("false")) {
                str_lit("bool")
            } else if string_eq_p(d, str_lit("nil")) {
                str_lit("nil")
            } else if string_eq_p(d, str_lit("%pairof")) {
                str_lit("pair")
            } else if string_eq_p(d, str_lit("symbol")) {
                str_lit("symbol")
            } else if string_eq_p(d, str_lit("%array")) {
                str_lit("bloblet")
            } else if string_eq_p(d, str_lit("%bytes")) {
                str_lit("bytevector")
            } else if string_eq_p(d, str_lit("%union")) {
                str_lit("union")
            } else {
                str_lit("")
            }
        }
        _ => {
            let other = tagcase_;
            str_lit("")
        }
    }
}

/// Members flattened: a union in a union is its members.
pub fn union_members(ts: Tys) -> Tys {
    if null_p(ts) {
        nil::<&'static Ty>()
    } else {
        let tagcase_ = car(ts);
        match *tagcase_ {
            Ty::TyData(d, args) => {
                if string_eq_p(d, str_lit("%union")) {
                    onto(union_members(args), union_members(cdr(ts)))
                } else {
                    kayak_rt::heap_cons(car(ts), union_members(cdr(ts)))
                }
            }
            _ => {
                let other = tagcase_;
                kayak_rt::heap_cons(car(ts), union_members(cdr(ts)))
            }
        }
    }
}

pub fn member_of_shape(mut ts: Tys, mut shape: Str) -> Tys {
    loop {
        if null_p(ts) {
            return nil::<&'static Ty>();
        } else if string_eq_p(shape_of(car(ts)), shape) {
            return kayak_rt::heap_cons(car(ts), kayak_rt::nil());
        } else {
            ts = cdr(ts);
            continue;
        }
    }
}

/// `tvars`: the type variables in scope.
pub fn parse_type(mut v: &'static Cv, mut tvars: Strings, mut t: &'static Sexp) -> &'static Ty {
    loop {
        let tagcase_ = t;
        match *tagcase_ {
            Sexp::Sym(s, at_file, at_pos) => {
                if string_eq_p(s, str_lit("i64")) {
                    return ty_i64();
                } else if string_eq_p(s, str_lit("int")) {
                    return ty_int();
                } else if string_eq_p(s, str_lit("nat")) {
                    return ty_nat();
                } else if string_eq_p(s, str_lit("f64")) {
                    return ty_f64();
                } else if fixed_width_p(s) {
                    return ty_data(s, nil::<&'static Ty>());
                } else if string_eq_p(s, str_lit("f32")) {
                    return ty_data(s, nil::<&'static Ty>());
                } else if string_eq_p(s, str_lit("symbol")) {
                    return ty_data(s, nil::<&'static Ty>());
                } else if string_eq_p(s, str_lit("false")) {
                    return ty_data(s, nil::<&'static Ty>());
                } else if string_eq_p(s, str_lit("nil")) {
                    return ty_data(s, nil::<&'static Ty>());
                } else if string_eq_p(s, str_lit("bool")) {
                    return ty_bool();
                } else if string_eq_p(s, str_lit("char")) {
                    return ty_char();
                } else if string_eq_p(s, str_lit("unit")) {
                    return ty_unit();
                } else if string_eq_p(s, str_lit("string")) {
                    return ty_string();
                } else if string_eq_p(s, str_lit("void")) {
                    return ty_void();
                } else if string_member_p(s, tvars) {
                    return ty_var(s);
                } else if (string_eq_p(s, str_lit("io-error")) && not(dt_named_p(s, cv_dts(v))) && null_p(find_alias(s, cv_aliases(v)))) {
                    t = car(read_all(string_chars(io_error_text()), str_lit(""), 1i64));
                    continue;
                } else if dt_named_p(s, cv_dts(v)) {
                    let tagcase_ = car(find_family(s, cv_dts(v)));
                    match *tagcase_ {
                        Dt::Dt(n, ps, vs) => {
                            if null_p(ps) {
                                return ty_data(s, nil::<&'static Ty>());
                            } else {
                                return match refuse(v, string_append(str_lit("a type with parameters, given none: "), s)) {};
                            }
                        }
                    }
                } else {
                    let found = find_alias(s, cv_aliases(v));
                    if null_p(found) {
                        return match refuse(v, string_append(str_lit("no type is named "), s)) {};
                    } else {
                        let tagcase_ = car(found);
                        match *tagcase_ {
                            Alias::Alias(n, ps, body) => {
                                if not(null_p(ps)) {
                                    return match refuse(v, string_append(str_lit("a type with parameters, given none: "), s)) {};
                                } else if string_member_p(string_append(str_lit("%expanding "), s), tvars) {
                                    return match refuse(v, string_append(str_lit("a type abbreviation that mentions itself, "), string_append(s, str_lit(": Rust's type aliases cannot; a datatype can")))) {};
                                } else if head_is_p(body, str_lit("moduleof")) {
                                    return ty_data(string_append(str_lit("%module "), s), nil::<&'static Ty>());
                                } else {
                                    (tvars, t) = (kayak_rt::heap_cons(string_append(str_lit("%expanding "), s), tvars), body);
                                    continue;
                                }
                            }
                        }
                    }
                }
            }
            Sexp::Lst(xs, src_file, src_line, src_pos) => {
                if sym_is_p(car(xs), str_lit("listof")) {
                    return no_knot(v, lambda1(move |x: Str| {
                        x
                    }), ty_list(parse_type(v, tvars, second(xs)), parse_region(v, tvars, third(xs))));
                } else if sym_is_p(car(xs), str_lit("flatarrayof")) {
                    if sym_is_p(second(xs), str_lit("i64")) {
                        return ty_flat(ty_i64(), parse_mutable_region(v, tvars, third(xs)));
                    } else {
                        return match refuse(v, string_append(str_lit("KFX-0's flat arrays are of i64: "), show_sexp(t))) {};
                    }
                } else if sym_is_p(car(xs), str_lit("bytevectorof")) {
                    // FX-26's bytes (C49), as kayak-rt's `Bytes`: at a region, written
                    // in place.
                    if i64_eq(size(xs), 2i64) {
                        return ty_data(str_lit("%bytes"), kayak_rt::heap_cons(parse_mutable_region(v, tvars, second(xs)), kayak_rt::nil()));
                    } else {
                        return match refuse(v, string_append(str_lit("(bytevectorof R): "), show_sexp(t))) {};
                    }
                } else if sym_is_p(car(xs), str_lit("ref")) {
                    return no_knot(v, lambda1(move |x: Str| {
                        x
                    }), ty_ref(parse_type(v, tvars, second(xs)), parse_mutable_region(v, tvars, third(xs))));
                } else if sym_is_p(car(xs), str_lit("place")) {
                    // `(place p)` (C34): a `letrena`'s place, or a poly's place binder.
                    let r = if i64_eq(size(xs), 2i64) {
                        let tagcase_ = second(xs);
                        match *tagcase_ {
                            Sexp::Sym(n, f, p) => {
                                n
                            }
                            _ => {
                                let other = tagcase_;
                                str_lit("")
                            }
                        }
                    } else {
                        str_lit("")
                    };
                    if string_member_p(string_append(str_lit("%place '"), r), tvars) {
                        return ty_data(str_lit("%place"), kayak_rt::heap_cons(ty_var(string_append(str_lit("'"), r)), kayak_rt::nil()));
                    } else {
                        return match refuse(v, string_append(str_lit("a place's type names a letrena's place or a poly's place binder: "), show_sexp(t))) {};
                    }
                } else if sym_is_p(car(xs), str_lit("bloblet")) {
                    // `(bloblet (fields T ...) R)` (C31): fields that may be written, so
                    // none a procedure or a type variable, which could tie a knot
                    // through the store that no type here shows.
                    if (not(i64_eq(size(xs), 3i64)) || not(head_is_p(second(xs), str_lit("fields")))) {
                        return match refuse(v, string_append(str_lit("a bloblet type KFX does not have yet (its fields frozen, or not of the form (bloblet (fields T ...) R)): "), show_sexp(t))) {};
                    } else {
                        let fields = parse_types(v, tvars, cdr(items(second(xs))));
                        if any_p(lambda1(move |f: &'static Ty| {
                            field_may_knot_p(f)
                        }), fields) {
                            return match refuse(v, string_append(str_lit("a bloblet field that may hold a procedure, which KFX does not have: "), show_sexp(t))) {};
                        } else {
                            return ty_data(str_lit("%bloblet"), kayak_rt::heap_cons(parse_mutable_region(v, tvars, third(xs)), fields));
                        }
                    }
                } else if sym_is_p(car(xs), str_lit("blobref")) {
                    if not(i64_eq(size(xs), 3i64)) {
                        return match refuse(v, str_lit("(blobref B F)")) {};
                    } else {
                        let (b, f) = (parse_type(v, tvars, second(xs)), parse_type(v, tvars, third(xs)));
                        if not({
                            let tagcase_ = b;
                            match *tagcase_ {
                                Ty::TyData(d, args) => {
                                    string_eq_p(d, str_lit("%bloblet"))
                                }
                                _ => {
                                    let other = tagcase_;
                                    false
                                }
                            }
                        }) {
                            return match refuse(v, string_append(str_lit("a blobref's owner is a bloblet: "), show_sexp(t))) {};
                        } else if not(flat_p(f)) {
                            return match refuse(v, string_append(str_lit("a blobref's flat is a scalar, or a product or array of them (KFX has no f32 yet): "), show_sexp(t))) {};
                        } else {
                            return ty_data(str_lit("%blobref"), kayak_rt::heap_cons(b, kayak_rt::heap_cons(f, kayak_rt::nil())));
                        }
                    }
                } else if (sym_is_p(car(xs), str_lit("arrayof")) && i64_eq(size(xs), 3i64) && {
                    let tagcase_ = third(xs);
                    match *tagcase_ {
                        Sexp::Num(k, f, p) => {
                            false
                        }
                        _ => {
                            let other = tagcase_;
                            true
                        }
                    }
                }) {
                    // An array of values (C56), `(arrayof T R)`, at a region: kayak-rt's
                    // `Array<T>`, a row of cells.
                    return no_knot(v, lambda1(move |x: Str| {
                        x
                    }), ty_data(str_lit("%array"), kayak_rt::heap_cons(parse_type(v, tvars, second(xs)), kayak_rt::heap_cons(parse_mutable_region(v, tvars, third(xs)), kayak_rt::nil()))));
                } else if sym_is_p(car(xs), str_lit("arrayof")) {
                    let tagcase_ = third(xs);
                    match *tagcase_ {
                        Sexp::Num(k, f, p) => {
                            let e = parse_type(v, tvars, second(xs));
                            if (not(i64_lt(k, 0i64)) && flat_p(e)) {
                                return ty_data(str_lit("%flat-array"), kayak_rt::heap_cons(e, kayak_rt::heap_cons(ty_rconst(i64_to_string(k)), kayak_rt::nil())));
                            } else {
                                return match refuse(v, string_append(str_lit("a flat array is of a flat, its length a literal (KFX has no arrays of values yet): "), show_sexp(t))) {};
                            }
                        }
                        _ => {
                            let other = tagcase_;
                            return match refuse(v, string_append(str_lit("a flat array's length is a literal (KFX has no arrays of values yet): "), show_sexp(t))) {};
                        }
                    }
                } else if (sym_is_p(car(xs), str_lit("pairof")) && i64_eq(size(xs), 4i64)) {
                    // FX-26's pair, never `nil` (C68): `(pairof A B R)`, its head and
                    // tail of any types; a list's pair when its tail is the list.
                    return ty_data(str_lit("%pairof"), kayak_rt::heap_cons(parse_type(v, tvars, second(xs)), kayak_rt::heap_cons(parse_type(v, tvars, third(xs)), kayak_rt::heap_cons(parse_mutable_region(v, tvars, fourth(xs)), kayak_rt::nil()))));
                } else if sym_is_p(car(xs), str_lit("union")) {
                    let members = union_members(parse_types(v, tvars, cdr(xs)));
                    let shapes = map(&shape_of, members);
                    if i64_lt(size(members), 2i64) {
                        return match refuse(v, string_append(str_lit("a union of fewer than two members: "), show_sexp(t))) {};
                    } else if string_member_p(str_lit(""), shapes) {
                        return match refuse(v, string_append(str_lit("a union's member with no shape known (a type variable, an abstract or generative type, a tag): "), show_sexp(t))) {};
                    } else if repeated_p(shapes) {
                        return match refuse(v, string_append(str_lit("a union of two members of one shape, which no test tells apart: "), show_sexp(t))) {};
                    } else {
                        return ty_data(str_lit("%union"), members);
                    }
                } else if (sym_is_p(car(xs), str_lit("composable")) && i64_eq(size(xs), 5i64)) {
                    // FX-26's composable continuation (C60), `(composable T A D R)`: a
                    // procedure of `T` to `A`, of effect `D` and control on `R`. Its own
                    // type, below that procedure's; never Rust's (the restriction pass).
                    return ty_data(str_lit("%composable"), kayak_rt::heap_cons(parse_type(v, tvars, second(xs)), kayak_rt::heap_cons(parse_type(v, tvars, third(xs)), kayak_rt::heap_cons(ty_proc(parse_effect(v, tvars, fourth(xs)), nil::<&'static Ty>(), ty_unit()), kayak_rt::heap_cons(parse_mutable_region(v, tvars, car(cdr(cdr(cdr(cdr(xs)))))), kayak_rt::nil())))));
                } else if sym_is_p(car(xs), str_lit("prompt-tag")) {
                    return ty_tag(parse_type(v, tvars, second(xs)), parse_type(v, tvars, third(xs)), parse_effect(v, tvars, fourth(xs)), parse_mutable_region(v, tvars, car(cdr(cdr(cdr(cdr(xs)))))));
                } else if sym_is_p(car(xs), str_lit("moduleof")) {
                    return match refuse(v, str_lit("a moduleof is a module's type when a define-type names it: KFX's is a Rust trait (C24)")) {};
                } else if (sym_is_p(car(xs), str_lit("sumof")) && not(null_p(cdr(xs))) && {
                    let tagcase_ = second(xs);
                    match *tagcase_ {
                        Sexp::Sym(n, f, p) => {
                            true
                        }
                        _ => {
                            let other = tagcase_;
                            false
                        }
                    }
                }) {
                    // A keyed flat sum, `(sumof u8 (0 F) (7 G))` (C33): a tag of the key's
                    // width, the label stored as it is, then the variant.
                    let key = sym_name(second(xs));
                    if not(string_member_p(key, kayak_rt::heap_cons(str_lit("u8"), kayak_rt::heap_cons(str_lit("u16"), kayak_rt::heap_cons(str_lit("u32"), kayak_rt::nil()))))) {
                        return match refuse(v, str_lit("a flat sum's key is `u8`, `u16` or `u32`")) {};
                    } else {
                        return ty_data(str_lit("%flat-sum"), kayak_rt::heap_cons(ty_rconst(key), concat(map(lambda1(move |g: &'static Sexp| {
                            let parts = {
                                let tagcase_ = g;
                                match *tagcase_ {
                                    Sexp::Lst(ys, f2, l2, p2) => {
                                        ys
                                    }
                                    _ => {
                                        let other = tagcase_;
                                        nil::<&'static Sexp>()
                                    }
                                }
                            };
                            if (not(i64_eq(size(parts), 2i64)) || {
                                let tagcase_ = car(parts);
                                match *tagcase_ {
                                    Sexp::Num(k, f3, p3) => {
                                        (i64_lt(k, 0i64) || not(i64_lt(k, key_range(key))))
                                    }
                                    _ => {
                                        let other = tagcase_;
                                        true
                                    }
                                }
                            }) {
                                match refuse(v, string_append(str_lit("a keyed flat sum's variant is (label flat), its label a number the key holds: "), show_sexp(t))) {}
                            } else {
                                let f = parse_type(v, tvars, second(parts));
                                if flat_p(f) {
                                    the::<Tys>(kayak_rt::heap_cons(ty_rconst(i64_to_string({
                                        let tagcase_ = car(parts);
                                        match *tagcase_ {
                                            Sexp::Num(k, f3, p3) => {
                                                k
                                            }
                                            _ => {
                                                let other = tagcase_;
                                                0i64
                                            }
                                        }
                                    })), kayak_rt::heap_cons(f, kayak_rt::nil())))
                                } else {
                                    match refuse(v, string_append(str_lit("a flat sum's variant is a flat: "), show_sexp(t))) {}
                                }
                            }
                        }), cdr(cdr(xs))))));
                    }
                } else if ((sym_is_p(car(xs), str_lit("productof")) || sym_is_p(car(xs), str_lit("sumof"))) && any_p(lambda1(move |x: &'static Sexp| {
                    let tagcase_ = x;
                    match *tagcase_ {
                        Sexp::Lst(ys, f, l, p) => {
                            false
                        }
                        _ => {
                            let other = tagcase_;
                            true
                        }
                    }
                }), cdr(xs))) {
                    return match refuse(v, string_append(str_lit("a type KFX does not have: "), show_sexp(t))) {};
                } else if (sym_is_p(car(xs), str_lit("productof")) || sym_is_p(car(xs), str_lit("sumof"))) {
                    let fields = map(&items, cdr(xs));
                    if (any_p(lambda1(move |f: Sexps| {
                        not(i64_eq(size(f), 2i64))
                    }), fields) || any_p(lambda1(move |f: Sexps| {
                        string_eq_p(label_of(car(f)), str_lit(""))
                    }), fields) || (sym_is_p(car(xs), str_lit("sumof")) && any_p(lambda1(move |f: Sexps| {
                        let tagcase_ = car(f);
                        match *tagcase_ {
                            Sexp::Sym(n, at_file, at_pos) => {
                                false
                            }
                            _ => {
                                let other = tagcase_;
                                true
                            }
                        }
                    }), fields))) {
                        return match refuse(v, string_append(str_lit("a type KFX does not have: "), show_sexp(t))) {};
                    } else {
                        if (any_p(lambda1(move |f: Sexps| {
                            let tagcase_ = car(f);
                            match *tagcase_ {
                                Sexp::Sym(n, at_file, at_pos) => {
                                    not(kfx_name_p(n))
                                }
                                _ => {
                                    let other = tagcase_;
                                    false
                                }
                            }
                        }), fields) || repeated_p(map(lambda1(move |f: Sexps| {
                            label_of(car(f))
                        }), fields)) || repeated_p(map(lambda1(move |f: Sexps| {
                            variant_name(label_of(car(f)))
                        }), fields))) {
                            return match refuse(v, string_append(str_lit("a label appears twice in "), show_sexp(t))) {};
                        } else {
                            return ty_shape(sym_is_p(car(xs), str_lit("productof")), map(lambda1(move |f: Sexps| {
                                label_of(car(f))
                            }), fields), map(lambda1(move |f: Sexps| {
                                parse_type(v, tvars, second(f))
                            }), fields));
                        }
                    }
                } else if sym_is_p(car(xs), str_lit("select")) {
                    let name = string_append(name_of(v, second(xs)), string_append(str_lit(" "), name_of(v, third(xs))));
                    if null_p(find_alias(name, cv_aliases(v))) {
                        return match refuse(v, string_append(str_lit("no module defined at the top level gives a type "), show_sexp(t))) {};
                    } else {
                        t = sym(name, str_lit(""), 0i64);
                        continue;
                    }
                } else if sym_is_p(car(xs), str_lit("subr")) {
                    return ty_proc(parse_effect(v, tvars, second(xs)), parse_types(v, tvars, items(third(xs))), parse_type(v, tvars, fourth(xs)));
                } else if {
                    let tagcase_ = car(xs);
                    match *tagcase_ {
                        Sexp::Sym(n, at_file, at_pos) => {
                            (dt_named_p(n, cv_dts(v)) || not(null_p(find_alias(n, cv_aliases(v)))))
                        }
                        _ => {
                            let other = tagcase_;
                            false
                        }
                    }
                } {
                    return no_knot(v, lambda1(move |x: Str| {
                        x
                    }), parse_application(v, tvars, name_of(v, car(xs)), cdr(xs)));
                } else {
                    return match refuse(v, string_append(str_lit("a type KFX does not have: "), show_sexp(t))) {};
                }
            }
            _ => {
                let other = tagcase_;
                return match refuse(v, string_append(str_lit("a type KFX does not have: "), show_sexp(t))) {};
            }
        }
    }
}

pub fn parse_types(v: &'static Cv, tvars: Strings, ts: Sexps) -> Tys {
    map(lambda1(move |t: &'static Sexp| {
        parse_type(v, tvars, t)
    }), ts)
}

/// A family's arguments, each read as its parameter's kind says: a
/// region for a name beginning `'`, a type otherwise.
pub fn parse_arguments(v: &'static Cv, tvars: Strings, params: Strings, args: Sexps) -> Tys {
    if (null_p(params) && null_p(args)) {
        nil::<&'static Ty>()
    } else if (null_p(params) || null_p(args)) {
        match refuse(v, str_lit("a type given the wrong number of arguments")) {}
    } else {
        kayak_rt::heap_cons(if char_eq_p(string_ref_i64(car(params), 0i64), '\'') {
            parse_region(v, tvars, car(args))
        } else if char_eq_p(string_ref_i64(car(params), 0i64), '~') {
            // An effect argument (C46): a row, its atoms, and `~!`, which
            // says the procedures there are of an effect binder's, and so
            // are in Rust as the family's own are, whatever is given.
            effect_row(kayak_rt::heap_cons(str_lit("~!"), parse_effect(v, tvars, car(args))))
        } else {
            parse_type(v, tvars, car(args))
        }, parse_arguments(v, tvars, cdr(params), cdr(args)))
    }
}

/// `(name arg ...)`: a datatype with parameters, applied; or a type
/// abbreviation with them, what it stands for with its arguments.
pub fn parse_application(v: &'static Cv, tvars: Strings, name: Str, args: Sexps) -> &'static Ty {
    let found = find_family(name, cv_dts(v));
    if not(null_p(found)) {
        let tagcase_ = car(found);
        match *tagcase_ {
            Dt::Dt(n, ps, vs) => {
                ty_data(name, parse_arguments(v, tvars, ps, args))
            }
        }
    } else {
        let tagcase_ = car(find_alias(name, cv_aliases(v)));
        match *tagcase_ {
            Alias::Alias(n, ps, body) => {
                if string_member_p(string_append(str_lit("%expanding "), name), tvars) {
                    match refuse(v, string_append(str_lit("a type abbreviation that mentions itself, "), string_append(name, str_lit(": Rust's type aliases cannot; a datatype can")))) {}
                } else {
                    substitute(ps, parse_arguments(v, tvars, ps, args), parse_type(v, kayak_rt::heap_cons(string_append(str_lit("%expanding "), name), onto(map(lambda1(move |p: Str| {
                        string_append(str_lit("%place "), p)
                    }), concat(map(lambda1(move |p: Str| {
                        if has_prefix_p(p, str_lit("'")) {
                            the::<Strings>(kayak_rt::heap_cons(p, kayak_rt::nil()))
                        } else {
                            nil::<Str>()
                        }
                    }), ps))), onto(ps, expanding(tvars)))), body))
                }
            }
        }
    }
}

/// A family's parameters, from its head `(name (p kind) ...)`: a type's
/// named as written, a region's with `'` first; none for a bare name.
pub fn family_params(v: &'static Cv, head: &'static Sexp) -> Strings {
    let tagcase_ = head;
    match *tagcase_ {
        Sexp::Lst(xs, src_file, src_line, src_pos) => {
            map(lambda1(move |b: &'static Sexp| {
                let b = items(b);
                if (i64_eq(size(b), 3i64) && sym_is_p(second(b), str_lit("region")) && not(sym_is_p(third(b), str_lit("distinct")))) {
                    // A region within a place, `(r region p)` (C40).
                    string_append(str_lit("'"), name_of(v, car(b)))
                } else if not(i64_eq(size(b), 2i64)) {
                    match refuse(v, string_append(str_lit("a variance mark, which KFX does not have (its families are invariant): "), show_sexp(lst(b, str_lit(""), 0i64, 0i64)))) {}
                } else if sym_is_p(second(b), str_lit("type")) {
                    name_of(v, car(b))
                } else if sym_is_p(second(b), str_lit("region")) {
                    string_append(str_lit("'"), name_of(v, car(b)))
                } else if sym_is_p(second(b), str_lit("place")) {
                    string_append(str_lit("'"), name_of(v, car(b)))
                } else if sym_is_p(second(b), str_lit("effect")) {
                    string_append(str_lit("~"), name_of(v, car(b)))
                } else {
                    match refuse(v, string_append(str_lit("a family over a kind KFX does not have: "), show_sexp(lst(b, str_lit(""), 0i64, 0i64)))) {}
                }
            }), cdr(xs))
        }
        _ => {
            let other = tagcase_;
            nil::<Str>()
        }
    }
}

/// A type's name as its own Rust scope writes it: `m t` and `m..t` are `t`.
pub fn bare_type_name(mut cs: Chars, mut acc: Chars) -> Str {
    loop {
        if null_p(cs) {
            return rev_to_string(acc);
        } else if (char_eq_p(car(cs), ' ') || char_eq_p(car(cs), '.')) {
            (cs, acc) = (cdr(cs), nil::<char>());
            continue;
        } else {
            (cs, acc) = (cdr(cs), kayak_rt::heap_cons(car(cs), acc));
            continue;
        }
    }
}

/// Type variables, a poly's or a family's, each a Rust type parameter of
/// its name camel-cased: each a KFX name (C27), none named as a type the
/// Rust names, as another of them, or as a type `types` has, which it
/// would hide in Rust and not in FX-26. A region's, with `'`, is none, nor
/// an effect's, with `~`, which Rust does not see (C46).
pub fn type_binders_apart(v: &'static Cv, tvars: Strings, types: Strings) -> () {
    let (reserved, theirs, tvars) = (rust_type_names(), map(lambda1(move |t: Str| {
        camel(bare_type_name(string_chars(t), nil::<char>()))
    }), types), concat(map(lambda1(move |n: Str| {
        if (has_prefix_p(n, str_lit("'")) || has_prefix_p(n, str_lit("~"))) {
            nil::<Str>()
        } else {
            the::<Strings>(kayak_rt::heap_cons(n, kayak_rt::nil()))
        }
    }), tvars)));
    map(lambda1(move |n: Str| {
        if not(kfx_name_p(n)) {
            match refuse(v, string_append(str_lit("a type variable's name KFX's names are not (C27): "), n)) {}
        } else if string_member_p(camel(n), reserved) {
            match refuse(v, string_append(str_lit("a type variable named as a type the Rust names: "), n)) {}
        } else if string_member_p(camel(n), theirs) {
            match refuse(v, string_append(str_lit("a type variable named as a type, which it would hide in Rust: "), n)) {}
        } else {
            ()
        }
    }), tvars);
    if repeated_p(map(&camel, tvars)) {
        match refuse(v, str_lit("two type variables named alike in Rust (camel-cased, as `a` and `a-`)")) {}
    } else {
        ()
    }
}

/// A definition's type's variables: a poly at its top, over types, and
/// regions, whose names begin with `'`; the program's `own`, held apart
/// from its types (a primitive's not).
pub fn poly_binders(v: &'static Cv, t: &'static Sexp, own: bool) -> Strings {
    if head_is_p(t, str_lit("poly")) {
        let tvars = map(lambda1(move |b: &'static Sexp| {
            let b = items(b);
            if (i64_eq(size(b), 3i64) && sym_is_p(second(b), str_lit("region")) && not(sym_is_p(third(b), str_lit("distinct")))) {
                // A region within a place, `(r region p)` (C40): its data may be
                // made in the place, which it will not outlive.
                string_append(str_lit("'"), name_of(v, car(b)))
            } else if not(i64_eq(size(b), 2i64)) {
                match refuse(v, string_append(str_lit("a binder KFX-0 does not have (distinct regions are to come): "), show_sexp(lst(b, str_lit(""), 0i64, 0i64)))) {}
            } else if sym_is_p(second(b), str_lit("type")) {
                name_of(v, car(b))
            } else if sym_is_p(second(b), str_lit("region")) {
                string_append(str_lit("'"), name_of(v, car(b)))
            } else if sym_is_p(second(b), str_lit("place")) {
                string_append(str_lit("'"), name_of(v, car(b)))
            } else if sym_is_p(second(b), str_lit("effect")) {
                string_append(str_lit("~"), name_of(v, car(b)))
            } else {
                match refuse(v, string_append(str_lit("KFX's poly is over types, effects, regions and places: "), show_sexp(lst(b, str_lit(""), 0i64, 0i64)))) {}
            }
        }), items(second(items(t))));
        if own {
            type_binders_apart(v, tvars, onto(map(lambda1(move |d: &'static Dt| {
                let tagcase_ = d;
                match *tagcase_ {
                    Dt::Dt(n, ps, vs) => {
                        n
                    }
                }
            }), cv_dts(v)), map(lambda1(move |a: &'static Alias| {
                let tagcase_ = a;
                match *tagcase_ {
                    Alias::Alias(n, ps, body) => {
                        n
                    }
                }
            }), cv_aliases(v))))
        } else {
            ()
        };
        tvars
    } else {
        nil::<Str>()
    }
}

/// A poly's place binders, `%place 'p` each: where `(place p)` may be
/// written (C34). A place is a region too, `'p`.
pub fn place_marks(t: &'static Sexp) -> Strings {
    if head_is_p(t, str_lit("poly")) {
        concat(map(lambda1(move |b: &'static Sexp| {
            let xs = items(b);
            if (i64_eq(size(xs), 2i64) && sym_is_p(second(xs), str_lit("place"))) {
                the::<Strings>(kayak_rt::heap_cons(string_append(str_lit("%place '"), sym_name(car(xs))), kayak_rt::nil()))
            } else if (i64_eq(size(xs), 3i64) && sym_is_p(second(xs), str_lit("region")) && not(sym_is_p(third(xs), str_lit("distinct")))) {
                the::<Strings>(kayak_rt::heap_cons(string_append(str_lit("%within '"), string_append(sym_name(car(xs)), string_append(str_lit(" '"), sym_name(third(xs))))), kayak_rt::nil()))
            } else {
                nil::<Str>()
            }
        }), items(second(items(t)))))
    } else {
        nil::<Str>()
    }
}

/// A `poly` directly in a `poly`, as FX-26 writes a primitive's binders by
/// kind (C70): one `poly`, the binders in order, which means the same.
pub fn flat_poly(t: &'static Sexp) -> &'static Sexp {
    if (head_is_p(t, str_lit("poly")) && i64_eq(size(items(t)), 3i64) && head_is_p(third(items(t)), str_lit("poly"))) {
        let inner = flat_poly(third(items(t)));
        lst(kayak_rt::heap_cons(car(items(t)), kayak_rt::heap_cons(lst(onto(items(second(items(t))), items(second(items(inner)))), str_lit(""), 0i64, 0i64), kayak_rt::heap_cons(third(items(inner)), kayak_rt::nil()))), datum_file(t), 0i64, datum_pos(t))
    } else {
        t
    }
}

pub fn parse_scheme_of(v: &'static Cv, t0: &'static Sexp, own: bool) -> &'static Scheme {
    let t = flat_poly(t0);
    let tvars = poly_binders(v, t, own);
    scheme(tvars, parse_type(v, onto(place_marks(t), tvars), if head_is_p(t, str_lit("poly")) {
        third(items(t))
    } else {
        t
    }))
}

pub fn parse_scheme(v: &'static Cv, t: &'static Sexp) -> &'static Scheme {
    parse_scheme_of(v, t, true)
}

pub fn show_ty(s: &'static St, t: &'static Ty) -> Str {
    let tagcase_ = walk(s, t);
    match *tagcase_ {
        Ty::TyI64() => {
            str_lit("i64")
        }
        Ty::TyInt() => {
            str_lit("int")
        }
        Ty::TyNat() => {
            str_lit("nat")
        }
        Ty::TyF64() => {
            str_lit("f64")
        }
        Ty::TyBool() => {
            str_lit("bool")
        }
        Ty::TyChar() => {
            str_lit("char")
        }
        Ty::TyUnit() => {
            str_lit("unit")
        }
        Ty::TyString() => {
            str_lit("string")
        }
        Ty::TyVoid() => {
            str_lit("void")
        }
        Ty::TyList(e, r) => {
            string_append(str_lit("(listof "), string_append(show_ty(s, e), string_append(str_lit(" "), string_append(show_ty(s, r), str_lit(")")))))
        }
        Ty::TyData(d, args) => {
            if null_p(args) {
                d
            } else if string_eq_p(d, str_lit("%bloblet")) {
                string_append(str_lit("(bloblet (fields "), string_append(show_tys(s, cdr(args)), string_append(str_lit(") "), string_append(show_ty(s, car(args)), str_lit(")")))))
            } else if string_eq_p(d, str_lit("%blobref")) {
                string_append(str_lit("(blobref "), string_append(show_tys(s, args), str_lit(")")))
            } else if string_eq_p(d, str_lit("%bytes")) {
                string_append(str_lit("(bytevectorof "), string_append(show_ty(s, car(args)), str_lit(")")))
            } else if string_eq_p(d, str_lit("%array")) {
                string_append(str_lit("(arrayof "), string_append(show_tys(s, args), str_lit(")")))
            } else if string_eq_p(d, str_lit("%union")) {
                string_append(str_lit("(union "), string_append(show_tys(s, args), str_lit(")")))
            } else if string_eq_p(d, str_lit("%pairof")) {
                string_append(str_lit("(pairof "), string_append(show_tys(s, args), str_lit(")")))
            } else if string_eq_p(d, str_lit("%composable")) {
                string_append(str_lit("(composable "), string_append(show_ty(s, car(args)), string_append(str_lit(" "), string_append(show_ty(s, car(cdr(args))), string_append(str_lit(" "), string_append({
                    let tagcase_ = car(cdr(cdr(args)));
                    match *tagcase_ {
                        Ty::TyProc(es, ps, r) => {
                            show_effs(es)
                        }
                        _ => {
                            let other = tagcase_;
                            str_lit("?")
                        }
                    }
                }, string_append(str_lit(" "), string_append(show_ty(s, car(cdr(cdr(cdr(args))))), str_lit(")")))))))))
            } else if string_eq_p(d, str_lit("%flat-array")) {
                string_append(str_lit("(arrayof "), string_append(show_tys(s, args), str_lit(")")))
            } else if string_eq_p(d, str_lit("%flat-sum")) {
                string_append(str_lit("(sumof "), string_append(show_ty(s, car(args)), string_append(run_together(map(lambda1(move |f: &'static Fvar| {
                    let tagcase_ = f;
                    match *tagcase_ {
                        Fvar::Fvar(l, x) => {
                            string_append(str_lit(" ("), string_append(l, string_append(str_lit(" "), string_append(show_ty(s, x), str_lit(")")))))
                        }
                    }
                }), flat_sum_variants(args))), str_lit(")"))))
            } else if string_eq_p(d, str_lit("%place")) {
                string_append(str_lit("(place "), string_append(show_tys(s, args), str_lit(")")))
            } else {
                string_append(str_lit("("), string_append(d, string_append(str_lit(" "), string_append(show_tys(s, args), str_lit(")")))))
            }
        }
        Ty::TyShape(p, ls, ts) => {
            string_append(if p {
                str_lit("(productof")
            } else {
                str_lit("(sumof")
            }, string_append(show_fields(s, ls, ts), str_lit(")")))
        }
        Ty::TyFlat(e, r) => {
            string_append(str_lit("(flatarrayof "), string_append(show_ty(s, e), string_append(str_lit(" "), string_append(show_ty(s, r), str_lit(")")))))
        }
        Ty::TyRef(e, r) => {
            string_append(str_lit("(ref "), string_append(show_ty(s, e), string_append(str_lit(" "), string_append(show_ty(s, r), str_lit(")")))))
        }
        Ty::TyRconst(n) => {
            n
        }
        Ty::TyTag(a, h, d, r) => {
            string_append(str_lit("(prompt-tag "), string_append(show_ty(s, a), string_append(str_lit(" "), string_append(show_ty(s, h), string_append(str_lit(" "), string_append(show_effs(d), string_append(str_lit(" "), string_append(show_ty(s, r), str_lit(")")))))))))
        }
        Ty::TyProc(es, ps, r) => {
            string_append(str_lit("(subr "), string_append(show_effs(es), string_append(str_lit(" ("), string_append(show_tys(s, ps), string_append(str_lit(") "), string_append(show_ty(s, r), str_lit(")")))))))
        }
        Ty::TyVar(n) => {
            n
        }
        Ty::TyMeta(k) => {
            string_append(str_lit("?"), i64_to_string(k))
        }
    }
}

pub fn show_fields(s: &'static St, ls: Strings, ts: Tys) -> Str {
    if (null_p(ls) || null_p(ts)) {
        str_lit("")
    } else {
        string_append(str_lit(" ("), string_append(car(ls), string_append(str_lit(" "), string_append(show_ty(s, car(ts)), string_append(str_lit(")"), show_fields(s, cdr(ls), cdr(ts)))))))
    }
}

pub fn show_tys(s: &'static St, ts: Tys) -> Str {
    if null_p(ts) {
        str_lit("")
    } else if null_p(cdr(ts)) {
        show_ty(s, car(ts))
    } else {
        string_append(show_ty(s, car(ts)), string_append(str_lit(" "), show_tys(s, cdr(ts))))
    }
}

/// `t`, its inference variable replaced by its solution, if it has one.
pub fn walk(mut s: &'static St, mut t: &'static Ty) -> &'static Ty {
    loop {
        let tagcase_ = t;
        match *tagcase_ {
            Ty::TyMeta(k) => {
                let tagcase_ = s;
                match *tagcase_ {
                    St::St(subst, next, fs) => {
                        let found = lookup_meta(k, subst);
                        if null_p(found) {
                            return t;
                        } else {
                            t = car(found);
                            continue;
                        }
                    }
                }
            }
            _ => {
                let other = tagcase_;
                return t;
            }
        }
    }
}

pub fn lookup_meta(mut k: i64, mut subst: Sbs) -> Tys {
    loop {
        if null_p(subst) {
            return nil::<&'static Ty>();
        } else {
            let tagcase_ = car(subst);
            match *tagcase_ {
                Sb::Sb(j, t) => {
                    if i64_eq(j, k) {
                        return kayak_rt::heap_cons(t, kayak_rt::nil());
                    } else {
                        subst = cdr(subst);
                        continue;
                    }
                }
            }
        }
    }
}

/// Whether `t` has an inference variable not solved yet.
pub fn has_meta_p(s: &'static St, t: &'static Ty) -> bool {
    let tagcase_ = walk(s, t);
    match *tagcase_ {
        Ty::TyMeta(k) => {
            true
        }
        Ty::TyList(e, r) => {
            (has_meta_p(s, e) || has_meta_p(s, r))
        }
        Ty::TyFlat(e, r) => {
            (has_meta_p(s, e) || has_meta_p(s, r))
        }
        Ty::TyShape(p, ls, ts) => {
            any_p(lambda1(move |x: &'static Ty| {
                has_meta_p(s, x)
            }), ts)
        }
        Ty::TyTag(a, h, d, r) => {
            (has_meta_p(s, a) || has_meta_p(s, h) || has_meta_p(s, r))
        }
        Ty::TyData(d, args) => {
            any_p(lambda1(move |x: &'static Ty| {
                has_meta_p(s, x)
            }), args)
        }
        Ty::TyRef(e, r) => {
            (has_meta_p(s, e) || has_meta_p(s, r))
        }
        Ty::TyProc(es, ps, r) => {
            (has_meta_p(s, r) || any_p(lambda1(move |p: &'static Ty| {
                has_meta_p(s, p)
            }), ps))
        }
        _ => {
            let other = tagcase_;
            false
        }
    }
}

/// A new inference variable.
pub fn fresh(s: &'static St) -> &'static Res {
    let tagcase_ = s;
    match *tagcase_ {
        St::St(subst, next, fs) => {
            res(ty_meta(next), nil::<Str>(), st(subst, i64_plus(next, 1i64), fs))
        }
    }
}

pub fn note_fact(s: &'static St, file: Str, pos: i64, what: Str) -> &'static St {
    let tagcase_ = s;
    match *tagcase_ {
        St::St(subst, next, fs) => {
            st(subst, next, kayak_rt::heap_cons(fact(file, pos, what), fs))
        }
    }
}

pub fn st_facts(s: &'static St) -> Facts {
    let tagcase_ = s;
    match *tagcase_ {
        St::St(subst, next, fs) => {
            fs
        }
    }
}

pub fn st_next(s: &'static St) -> i64 {
    let tagcase_ = s;
    match *tagcase_ {
        St::St(subst, next, fs) => {
            next
        }
    }
}

pub fn solve(s: &'static St, k: i64, t: &'static Ty) -> &'static St {
    let tagcase_ = s;
    match *tagcase_ {
        St::St(subst, next, fs) => {
            st(kayak_rt::heap_cons(sb(k, t), subst), next, fs)
        }
    }
}

pub fn occurs_p(s: &'static St, k: i64, t: &'static Ty) -> bool {
    let tagcase_ = walk(s, t);
    match *tagcase_ {
        Ty::TyMeta(j) => {
            i64_eq(j, k)
        }
        Ty::TyList(e, r) => {
            (occurs_p(s, k, e) || occurs_p(s, k, r))
        }
        Ty::TyFlat(e, r) => {
            (occurs_p(s, k, e) || occurs_p(s, k, r))
        }
        Ty::TyShape(p, ls, ts) => {
            any_p(lambda1(move |x: &'static Ty| {
                occurs_p(s, k, x)
            }), ts)
        }
        Ty::TyTag(a, h, d, r) => {
            (occurs_p(s, k, a) || occurs_p(s, k, h) || occurs_p(s, k, r))
        }
        Ty::TyData(d, args) => {
            any_p(lambda1(move |x: &'static Ty| {
                occurs_p(s, k, x)
            }), args)
        }
        Ty::TyRef(e, r) => {
            (occurs_p(s, k, e) || occurs_p(s, k, r))
        }
        Ty::TyProc(es, ps, r) => {
            (occurs_p(s, k, r) || any_p(lambda1(move |p: &'static Ty| {
                occurs_p(s, k, p)
            }), ps))
        }
        _ => {
            let other = tagcase_;
            false
        }
    }
}

pub fn same_base_p(a: &'static Ty, e: &'static Ty) -> bool {
    let tagcase_ = a;
    match *tagcase_ {
        Ty::TyI64() => {
            let tagcase_ = e;
            match *tagcase_ {
                Ty::TyI64() => {
                    true
                }
                _ => {
                    let other = tagcase_;
                    false
                }
            }
        }
        Ty::TyInt() => {
            let tagcase_ = e;
            match *tagcase_ {
                Ty::TyInt() => {
                    true
                }
                _ => {
                    let other = tagcase_;
                    false
                }
            }
        }
        Ty::TyNat() => {
            let tagcase_ = e;
            match *tagcase_ {
                Ty::TyNat() => {
                    true
                }
                Ty::TyInt() => {
                    true
                }
                _ => {
                    let other = tagcase_;
                    false
                }
            }
        }
        Ty::TyF64() => {
            let tagcase_ = e;
            match *tagcase_ {
                Ty::TyF64() => {
                    true
                }
                _ => {
                    let other = tagcase_;
                    false
                }
            }
        }
        Ty::TyBool() => {
            let tagcase_ = e;
            match *tagcase_ {
                Ty::TyBool() => {
                    true
                }
                _ => {
                    let other = tagcase_;
                    false
                }
            }
        }
        Ty::TyChar() => {
            let tagcase_ = e;
            match *tagcase_ {
                Ty::TyChar() => {
                    true
                }
                _ => {
                    let other = tagcase_;
                    false
                }
            }
        }
        Ty::TyUnit() => {
            let tagcase_ = e;
            match *tagcase_ {
                Ty::TyUnit() => {
                    true
                }
                _ => {
                    let other = tagcase_;
                    false
                }
            }
        }
        Ty::TyString() => {
            let tagcase_ = e;
            match *tagcase_ {
                Ty::TyString() => {
                    true
                }
                _ => {
                    let other = tagcase_;
                    false
                }
            }
        }
        _ => {
            let other = tagcase_;
            false
        }
    }
}

pub fn region_string(s: &'static St, r: &'static Ty) -> Str {
    let tagcase_ = walk(s, r);
    match *tagcase_ {
        Ty::TyRconst(n) => {
            n
        }
        Ty::TyVar(n) => {
            n
        }
        Ty::TyMeta(k) => {
            meta_name(k)
        }
        _ => {
            let other = tagcase_;
            str_lit("?")
        }
    }
}

/// A composable continuation as the procedure it is (C60): of its `D`, and
/// control on its region; any other type, itself.
pub fn composable_as_proc(s: &'static St, t: &'static Ty) -> &'static Ty {
    let tagcase_ = t;
    match *tagcase_ {
        Ty::TyData(d, args) => {
            if string_eq_p(d, str_lit("%composable")) {
                let r = region_string(s, car(cdr(cdr(cdr(args)))));
                ty_proc(effs_union(kayak_rt::heap_cons(string_append(str_lit("goto:"), r), kayak_rt::heap_cons(string_append(str_lit("comefrom:"), r), kayak_rt::nil())), {
                    let tagcase_ = car(cdr(cdr(args)));
                    match *tagcase_ {
                        Ty::TyProc(es, ps, x) => {
                            es
                        }
                        _ => {
                            let other = tagcase_;
                            nil::<Str>()
                        }
                    }
                }), kayak_rt::heap_cons(car(args), kayak_rt::nil()), car(cdr(args)))
            } else {
                t
            }
        }
        _ => {
            let other = tagcase_;
            t
        }
    }
}

/// The number of an inference variable's name, `?k`.
pub fn meta_number(r: Str) -> i64 {
    i64_minus(0i64, digits_value(cdr(string_chars(r)), 0i64, str_lit(""), 0i64))
}

pub fn chars_after_colon(mut cs: Chars) -> Str {
    loop {
        if null_p(cs) {
            return str_lit("");
        } else if char_eq_p(car(cs), ':') {
            return rev_to_string(rev_onto(cdr(cs), nil::<char>()));
        } else {
            cs = cdr(cs);
            continue;
        }
    }
}

pub fn effect_region(e: Str) -> Str {
    chars_after_colon(string_chars(e))
}

/// Whether `t` has an inference variable not solved yet, a latent
/// effect's region too (`(goto ?k)`): as FX-26 counts what a parameter's
/// type mentions that is not known.
pub fn open_effects_p(mut s: &'static St, mut t: &'static Ty) -> bool {
    loop {
        let tagcase_ = walk(s, t);
        match *tagcase_ {
            Ty::TyProc(es, ps, r) => {
                return (any_p(lambda1(move |e: Str| {
                    let at = effect_region(e);
                    (has_prefix_p(at, str_lit("?")) && {
                        let tagcase_ = walk(s, ty_meta(meta_number(at)));
                        match *tagcase_ {
                            Ty::TyMeta(k) => {
                                true
                            }
                            _ => {
                                let other = tagcase_;
                                false
                            }
                        }
                    })
                }), es) || open_effects_p(s, r) || any_p(lambda1(move |p: &'static Ty| {
                    open_effects_p(s, p)
                }), ps));
            }
            Ty::TyList(e, r) => {
                t = e;
                continue;
            }
            Ty::TyRef(e, r) => {
                t = e;
                continue;
            }
            Ty::TyData(d, args) => {
                return any_p(lambda1(move |x: &'static Ty| {
                    open_effects_p(s, x)
                }), args);
            }
            Ty::TyShape(p, ls, ts) => {
                return any_p(lambda1(move |x: &'static Ty| {
                    open_effects_p(s, x)
                }), ts);
            }
            _ => {
                let other = tagcase_;
                return false;
            }
        }
    }
}

pub fn has_open_p(s: &'static St, t: &'static Ty) -> bool {
    (has_meta_p(s, t) || open_effects_p(s, t))
}

pub fn after_colon(mut cs: List<char>) -> List<char> {
    loop {
        if null_p(cs) {
            return nil::<char>();
        } else if char_eq_p(car(cs), ':') {
            return cdr(cs);
        } else {
            cs = cdr(cs);
            continue;
        }
    }
}

pub fn region_atom_p(x: Str) -> bool {
    (i64_gt(string_length_i64(x), 5i64) && (string_eq_p(substring_of(x, 5i64), str_lit("read:")) || string_eq_p(substring_of(x, 5i64), str_lit("goto:")) || string_eq_p(substring_of(x, 6i64), str_lit("write:")) || string_eq_p(substring_of(x, 6i64), str_lit("alloc:")) || has_prefix_p(x, str_lit("comefrom:"))))
}

pub fn atom_kind(x: Str) -> Str {
    substring_of(x, i64_minus(string_length_i64(x), size(after_colon(string_to_list(x)))))
}

pub fn atom_region(x: Str) -> Str {
    list_to_string(after_colon(string_to_list(x)))
}

/// An effect atom, its region an inference variable solved replaced by
/// the region found.
pub fn resolve_atom(s: &'static St, x: Str) -> Str {
    let r = atom_region(x);
    if (region_atom_p(x) && char_eq_p(string_ref_i64(r, 0i64), '?')) {
        string_append(atom_kind(x), region_string(s, ty_meta(meta_number(r))))
    } else {
        x
    }
}

/// `t`, every inference variable in it replaced by its solution.
pub fn zonk(s: &'static St, t: &'static Ty) -> &'static Ty {
    let tagcase_ = walk(s, t);
    match *tagcase_ {
        Ty::TyList(e, r) => {
            ty_list(zonk(s, e), zonk(s, r))
        }
        Ty::TyFlat(e, r) => {
            ty_flat(zonk(s, e), zonk(s, r))
        }
        Ty::TyShape(p, ls, ts) => {
            ty_shape(p, ls, map(lambda1(move |x: &'static Ty| {
                zonk(s, x)
            }), ts))
        }
        Ty::TyTag(a, h, d, r) => {
            ty_tag(zonk(s, a), zonk(s, h), d, zonk(s, r))
        }
        Ty::TyData(d, args) => {
            ty_data(d, map(lambda1(move |x: &'static Ty| {
                zonk(s, x)
            }), args))
        }
        Ty::TyRef(e, r) => {
            ty_ref(zonk(s, e), zonk(s, r))
        }
        Ty::TyProc(es, ps, r) => {
            ty_proc(es, map(lambda1(move |p: &'static Ty| {
                zonk(s, p)
            }), ps), zonk(s, r))
        }
        _ => {
            let other = tagcase_;
            other
        }
    }
}

pub fn region_ty(r: Str) -> &'static Ty {
    if char_eq_p(string_ref_i64(r, 0i64), '?') {
        ty_meta(meta_number(r))
    } else if char_eq_p(string_ref_i64(r, 0i64), '\'') {
        ty_var(r)
    } else {
        ty_rconst(r)
    }
}

/// Of the effect `es`, an atom of the kind of `x` whose region is an
/// inference variable not solved: that variable can stand for `x`'s
/// region.
pub fn open_atom(mut s: &'static St, mut x: Str, mut es: Strings) -> Strings {
    loop {
        if null_p(es) {
            return nil::<Str>();
        } else if {
            let y = resolve_atom(s, car(es));
            (region_atom_p(y) && string_eq_p(atom_kind(y), atom_kind(x)) && char_eq_p(string_ref_i64(atom_region(y), 0i64), '?'))
        } {
            return kayak_rt::heap_cons(resolve_atom(s, car(es)), kayak_rt::nil());
        } else {
            es = cdr(es);
            continue;
        }
    }
}

// Effect variables (C46): a poly's effect binder is an atom `~e`; at a
// call, an inference variable, `~?k`, solved to a row: `(ty-proc atoms nil
// unit)` holds its atoms, the last of which may be another variable, open
// for more.
pub fn effect_meta_p(x: Str) -> bool {
    has_prefix_p(x, str_lit("~?"))
}

/// `es`, each effect variable solved replaced by its atoms.
pub fn expand_effs(s: &'static St, es: Strings) -> Strings {
    if null_p(es) {
        nil::<Str>()
    } else {
        effs_union(if effect_meta_p(car(es)) {
            let tagcase_ = walk(s, ty_meta(meta_number(after_prefix(car(es), str_lit("~")))));
            match *tagcase_ {
                Ty::TyProc(r#as, ps, r) => {
                    expand_effs(s, r#as)
                }
                _ => {
                    let other = tagcase_;
                    kayak_rt::heap_cons(car(es), kayak_rt::nil())
                }
            }
        } else {
            kayak_rt::heap_cons(car(es), kayak_rt::nil())
        }, expand_effs(s, cdr(es)))
    }
}

/// The effect variables of `es`, expanded: those not solved.
pub fn open_row(mut es: Strings) -> Strings {
    loop {
        if null_p(es) {
            return nil::<Str>();
        } else if effect_meta_p(car(es)) {
            return kayak_rt::heap_cons(car(es), open_row(cdr(es)));
        } else {
            es = cdr(es);
            continue;
        }
    }
}

pub fn closed_row(mut es: Strings) -> Strings {
    loop {
        if null_p(es) {
            return nil::<Str>();
        } else if effect_meta_p(car(es)) {
            es = cdr(es);
            continue;
        } else {
            return kayak_rt::heap_cons(car(es), closed_row(cdr(es)));
        }
    }
}

/// A call's effect: its effect variables' atoms, and none for a variable
/// nothing said, as FX-26 instantiates an effect binder no argument
/// names (pure).
pub fn close_effs(s: &'static St, es: Strings) -> Strings {
    closed_row(expand_effs(s, es))
}

/// Whether effect `a` is within `e`, an inference variable for a region
/// in `e` solved for one in `a` if need be, and one for an effect in `e`
/// grown to hold an atom of `a` (C46): the state, or none.
pub fn fit_effs(mut s: &'static St, mut a: Strings, mut e: Strings) -> List<&'static St> {
    loop {
        if null_p(a) {
            return kayak_rt::heap_cons(s, kayak_rt::nil());
        } else {
            let ax = expand_effs(s, a);
            let es = map(lambda1(move |y: Str| {
                resolve_atom(s, y)
            }), expand_effs(s, e));
            if null_p(ax) {
                return kayak_rt::heap_cons(s, kayak_rt::nil());
            } else {
                let x = resolve_atom(s, car(ax));
                if effs_within_p(kayak_rt::heap_cons(x, kayak_rt::nil()), es) {
                    a = cdr(ax);
                    continue;
                } else if effect_meta_p(x) {
                    // An effect variable of `a` not solved, that `e` does not hold:
                    // nothing more, the least it may be.
                    (s, a) = (solve(s, meta_number(after_prefix(x, str_lit("~"))), effect_row(nil::<Str>())), cdr(ax));
                    continue;
                } else if not(null_p(open_atom(s, x, e))) {
                    let tagcase_ = region_ty(atom_region(car(open_atom(s, x, e))));
                    match *tagcase_ {
                        Ty::TyMeta(k) => {
                            (s, a) = (solve(s, k, region_ty(atom_region(x))), cdr(ax));
                            continue;
                        }
                        _ => {
                            let other = tagcase_;
                            return nil::<&'static St>();
                        }
                    }
                } else if not(null_p(open_row(es))) {
                    let tagcase_ = fresh(s);
                    match *tagcase_ {
                        Res::Res(m, u, s) => {
                            let tagcase_ = m;
                            match *tagcase_ {
                                Ty::TyMeta(j) => {
                                    return fit_effs(solve(s, meta_number(after_prefix(car(open_row(es)), str_lit("~"))), effect_row(kayak_rt::heap_cons(x, kayak_rt::heap_cons(string_append(str_lit("~"), meta_name(j)), kayak_rt::nil())))), cdr(ax), e);
                                }
                                _ => {
                                    let other = tagcase_;
                                    return nil::<&'static St>();
                                }
                            }
                        }
                    }
                } else {
                    return nil::<&'static St>();
                }
            }
        }
    }
}

/// Effects `a` and `b` the same, each within the other, an effect variable
/// on either side solved to make them so (C60): the side open grown first,
/// so that its variable is not taken for the least it may be.
pub fn same_effs(s: &'static St, a: Strings, b: Strings) -> List<&'static St> {
    let grown = fit_effs(s, b, a);
    if (not(null_p(grown)) && not(null_p(fit_effs(car(grown), a, b)))) {
        fit_effs(car(grown), a, b)
    } else {
        let other = fit_effs(s, a, b);
        if null_p(other) {
            nil::<&'static St>()
        } else {
            fit_effs(car(other), b, a)
        }
    }
}

/// That a value of type `actual` may stand where `expected` is: the two
/// the same, inference variables solved to make them so, but for
/// `void`, which fits anything, and a procedure, whose latent effect
/// may be within the one expected.
pub fn fits(v: &'static Cv, s: &'static St, actual: &'static Ty, expected: &'static Ty) -> &'static St {
    let (a, e) = (walk(s, actual), walk(s, expected));
    let tagcase_ = a;
    match *tagcase_ {
        Ty::TyVoid() => {
            s
        }
        Ty::TyMeta(k) => {
            let tagcase_ = e;
            match *tagcase_ {
                Ty::TyMeta(j) => {
                    if i64_eq(j, k) {
                        s
                    } else {
                        solve(s, k, e)
                    }
                }
                _ => {
                    let other = tagcase_;
                    if occurs_p(s, k, e) {
                        mismatch(v, s, a, e)
                    } else {
                        solve(s, k, e)
                    }
                }
            }
        }
        _ => {
            let other = tagcase_;
            let tagcase_ = e;
            match *tagcase_ {
                Ty::TyMeta(j) => {
                    if occurs_p(s, j, a) {
                        mismatch(v, s, a, e)
                    } else if {
                        let tagcase_ = a;
                        match *tagcase_ {
                            Ty::TyNat() => {
                                true
                            }
                            _ => {
                                let other = tagcase_;
                                false
                            }
                        }
                    } {
                        // A `nat` met by an inference variable makes it an `int`: FX-26's
                        // is the variable's own `(nat v)`, which no other `nat` is.
                        solve(s, j, ty_int())
                    } else {
                        solve(s, j, a)
                    }
                }
                _ => {
                    let other = tagcase_;
                    fits_shapes(v, s, a, e)
                }
            }
        }
    }
}

pub fn fits_shapes(v: &'static Cv, s: &'static St, a: &'static Ty, e: &'static Ty) -> &'static St {
    if string_eq_p(shape_of(a), str_lit("union")) {
        // A union below `e`: each member is (C62).
        fits_each_member(v, s, {
            let tagcase_ = a;
            match *tagcase_ {
                Ty::TyData(d, args) => {
                    args
                }
                _ => {
                    let other = tagcase_;
                    nil::<&'static Ty>()
                }
            }
        }, e)
    } else if (string_eq_p(shape_of(e), str_lit("union")) && {
        let tagcase_ = a;
        match *tagcase_ {
            Ty::TyList(x, r) => {
                true
            }
            _ => {
                let other = tagcase_;
                false
            }
        }
    } && null_p(member_of_shape({
        let tagcase_ = e;
        match *tagcase_ {
            Ty::TyData(d, args) => {
                args
            }
            _ => {
                let other = tagcase_;
                nil::<&'static Ty>()
            }
        }
    }, str_lit("list")))) {
        // A list where a union of `nil` and a pair is expected: each of the
        // two it is (C69).
        let tagcase_ = a;
        match *tagcase_ {
            Ty::TyList(x, r) => {
                fits(v, fits(v, s, ty_data(str_lit("nil"), nil::<&'static Ty>()), e), ty_data(str_lit("%pairof"), kayak_rt::heap_cons(x, kayak_rt::heap_cons(a, kayak_rt::heap_cons(r, kayak_rt::nil())))), e)
            }
            _ => {
                let other = tagcase_;
                mismatch(v, s, a, e)
            }
        }
    } else if (string_eq_p(shape_of(e), str_lit("union")) && not(string_eq_p(shape_of(a), str_lit("")))) {
        // A member below its union: the member of its shape (C62).
        let m = member_of_shape({
            let tagcase_ = e;
            match *tagcase_ {
                Ty::TyData(d, args) => {
                    args
                }
                _ => {
                    let other = tagcase_;
                    nil::<&'static Ty>()
                }
            }
        }, shape_of(a));
        if null_p(m) {
            mismatch(v, s, a, e)
        } else {
            fits(v, s, a, car(m))
        }
    } else if ({
        let tagcase_ = a;
        match *tagcase_ {
            Ty::TyData(d, args) => {
                string_eq_p(d, str_lit("false"))
            }
            _ => {
                let other = tagcase_;
                false
            }
        }
    } && {
        let tagcase_ = e;
        match *tagcase_ {
            Ty::TyBool() => {
                true
            }
            _ => {
                let other = tagcase_;
                false
            }
        }
    }) {
        // `false` below `bool`.
        s
    } else if ({
        let tagcase_ = a;
        match *tagcase_ {
            Ty::TyData(d, args) => {
                string_eq_p(d, str_lit("nil"))
            }
            _ => {
                let other = tagcase_;
                false
            }
        }
    } && {
        let tagcase_ = e;
        match *tagcase_ {
            Ty::TyList(x, r) => {
                true
            }
            _ => {
                let other = tagcase_;
                false
            }
        }
    }) {
        // `nil` below a list (C68).
        s
    } else if ({
        let tagcase_ = a;
        match *tagcase_ {
            Ty::TyData(d, args) => {
                string_eq_p(d, str_lit("%pairof"))
            }
            _ => {
                let other = tagcase_;
                false
            }
        }
    } && {
        let tagcase_ = e;
        match *tagcase_ {
            Ty::TyList(x, r) => {
                true
            }
            _ => {
                let other = tagcase_;
                false
            }
        }
    }) {
        // A pair whose tail is the list, below the list (C68).
        let tagcase_ = a;
        match *tagcase_ {
            Ty::TyData(d, args) => {
                let tagcase_ = e;
                match *tagcase_ {
                    Ty::TyList(x, r) => {
                        fits(v, fits(v, fits(v, s, car(args), x), car(cdr(args)), e), car(cdr(cdr(args))), r)
                    }
                    _ => {
                        let other = tagcase_;
                        mismatch(v, s, a, e)
                    }
                }
            }
            _ => {
                let other = tagcase_;
                mismatch(v, s, a, e)
            }
        }
    } else {
        fits_shapes_of(v, s, a, e)
    }
}

pub fn fits_each_member(mut v: &'static Cv, mut s: &'static St, mut ms: Tys, mut e: &'static Ty) -> &'static St {
    loop {
        if null_p(ms) {
            return s;
        } else {
            (s, ms) = (fits(v, s, car(ms), e), cdr(ms));
            continue;
        }
    }
}

pub fn fits_shapes_of(v: &'static Cv, s: &'static St, a: &'static Ty, e: &'static Ty) -> &'static St {
    let tagcase_ = a;
    match *tagcase_ {
        Ty::TyList(x, xr) => {
            let tagcase_ = e;
            match *tagcase_ {
                Ty::TyList(y, yr) => {
                    fits(v, fits(v, s, x, y), xr, yr)
                }
                _ => {
                    let other = tagcase_;
                    mismatch(v, s, a, e)
                }
            }
        }
        Ty::TyFlat(x, xr) => {
            let tagcase_ = e;
            match *tagcase_ {
                Ty::TyFlat(y, yr) => {
                    fits(v, fits(v, s, x, y), xr, yr)
                }
                _ => {
                    let other = tagcase_;
                    mismatch(v, s, a, e)
                }
            }
        }
        Ty::TyShape(p, ls, ts) => {
            let tagcase_ = e;
            match *tagcase_ {
                Ty::TyShape(q, ms, us) => {
                    if (if p {
                        q
                    } else {
                        not(q)
                    } && strings_eq_p(ls, ms) && i64_eq(size(ts), size(us))) {
                        fits_each(v, s, ts, us)
                    } else {
                        mismatch(v, s, a, e)
                    }
                }
                _ => {
                    let other = tagcase_;
                    mismatch(v, s, a, e)
                }
            }
        }
        Ty::TyRef(x, xr) => {
            let tagcase_ = e;
            match *tagcase_ {
                Ty::TyRef(y, yr) => {
                    fits(v, fits(v, s, x, y), xr, yr)
                }
                _ => {
                    let other = tagcase_;
                    mismatch(v, s, a, e)
                }
            }
        }
        Ty::TyRconst(x) => {
            let tagcase_ = e;
            match *tagcase_ {
                Ty::TyRconst(y) => {
                    if string_eq_p(x, y) {
                        s
                    } else {
                        mismatch(v, s, a, e)
                    }
                }
                _ => {
                    let other = tagcase_;
                    mismatch(v, s, a, e)
                }
            }
        }
        Ty::TyTag(xa, xh, xd, xr) => {
            let tagcase_ = e;
            match *tagcase_ {
                Ty::TyTag(ya, yh, yd, yr) => {
                    // A tag's bound the same both ways, its effect variables solved to
                    // make it so (C60: a primitive's tag at FX-26's poly type).
                    let two = same_effs(s, xd, yd);
                    if null_p(two) {
                        mismatch(v, s, a, e)
                    } else {
                        fits(v, fits(v, fits(v, car(two), xa, ya), xh, yh), xr, yr)
                    }
                }
                _ => {
                    let other = tagcase_;
                    mismatch(v, s, a, e)
                }
            }
        }
        Ty::TyData(x, xs) => {
            let tagcase_ = e;
            match *tagcase_ {
                Ty::TyData(y, ys) => {
                    if not((string_eq_p(x, y) && i64_eq(size(xs), size(ys)))) {
                        mismatch(v, s, a, e)
                    } else if string_eq_p(x, str_lit("%composable")) {
                        // Its bound `D` the same both ways, as a tag's (C60).
                        let xd = {
                            let tagcase_ = car(cdr(cdr(xs)));
                            match *tagcase_ {
                                Ty::TyProc(es, ps, r) => {
                                    es
                                }
                                _ => {
                                    let other = tagcase_;
                                    nil::<Str>()
                                }
                            }
                        };
                        let yd = {
                            let tagcase_ = car(cdr(cdr(ys)));
                            match *tagcase_ {
                                Ty::TyProc(es, ps, r) => {
                                    es
                                }
                                _ => {
                                    let other = tagcase_;
                                    nil::<Str>()
                                }
                            }
                        };
                        let two = same_effs(s, xd, yd);
                        if null_p(two) {
                            mismatch(v, s, a, e)
                        } else {
                            fits(v, fits(v, fits(v, car(two), car(xs), car(ys)), car(cdr(xs)), car(cdr(ys))), car(cdr(cdr(cdr(xs)))), car(cdr(cdr(cdr(ys)))))
                        }
                    } else {
                        fits_all(v, s, xs, ys)
                    }
                }
                Ty::TyProc(ees, eps, er) => {
                    // A composable continuation where a procedure is expected (C60).
                    if string_eq_p(x, str_lit("%composable")) {
                        fits(v, s, composable_as_proc(s, a), e)
                    } else {
                        mismatch(v, s, a, e)
                    }
                }
                _ => {
                    let other = tagcase_;
                    mismatch(v, s, a, e)
                }
            }
        }
        Ty::TyVar(x) => {
            let tagcase_ = e;
            match *tagcase_ {
                Ty::TyVar(y) => {
                    if string_eq_p(x, y) {
                        s
                    } else {
                        mismatch(v, s, a, e)
                    }
                }
                _ => {
                    let other = tagcase_;
                    mismatch(v, s, a, e)
                }
            }
        }
        Ty::TyProc(aes, aps, ar) => {
            let tagcase_ = e;
            match *tagcase_ {
                Ty::TyProc(ees, eps, er) => {
                    if not(i64_eq(size(aps), size(eps))) {
                        mismatch(v, s, a, e)
                    } else if null_p(fit_effs(s, aes, ees)) {
                        mismatch(v, s, a, e)
                    } else {
                        fits(v, fits_all(v, car(fit_effs(s, aes, ees)), eps, aps), ar, er)
                    }
                }
                _ => {
                    let other = tagcase_;
                    mismatch(v, s, a, e)
                }
            }
        }
        _ => {
            let other = tagcase_;
            if same_base_p(a, e) {
                s
            } else {
                mismatch(v, s, a, e)
            }
        }
    }
}

/// Fields, or a sum's members: each actual's type standing for the
/// expected's, covariant.
pub fn fits_each(mut v: &'static Cv, mut s: &'static St, mut actuals: Tys, mut expecteds: Tys) -> &'static St {
    loop {
        if null_p(actuals) {
            return s;
        } else {
            (s, actuals, expecteds) = (fits(v, s, car(actuals), car(expecteds)), cdr(actuals), cdr(expecteds));
            continue;
        }
    }
}

/// Parameters: each expected parameter's type stands for the actual's.
pub fn fits_all(mut v: &'static Cv, mut s: &'static St, mut actuals: Tys, mut expecteds: Tys) -> &'static St {
    loop {
        if null_p(actuals) {
            return s;
        } else {
            (s, actuals, expecteds) = (fits(v, s, car(actuals), car(expecteds)), cdr(actuals), cdr(expecteds));
            continue;
        }
    }
}

pub fn mismatch(v: &'static Cv, s: &'static St, a: &'static Ty, e: &'static Ty) -> &'static St {
    match refuse(v, string_append(str_lit("a "), string_append(show_ty(s, a), string_append(str_lit(" is here, where a "), string_append(show_ty(s, e), str_lit(" is expected")))))) {}
}

// A scheme's instance: each variable an inference variable; those for
// regions are kept, so that a call's effect can name the regions found.
pub enum Inst {
    Inst(&'static Ty, &'static St, List<i64>, List<i64>),
}

pub fn inst(f0: &'static Ty, f1: &'static St, f2: List<i64>, f3: List<i64>) -> &'static Inst {
    kayak_rt::heap_alloc(Inst::Inst(f0, f1, f2, f3))
}

pub fn instantiate(s: &'static St, sc: &'static Scheme) -> &'static Inst {
    let tagcase_ = sc;
    match *tagcase_ {
        Scheme::Scheme(tvars, t) => {
            instantiate_vars(s, tvars, t, nil::<i64>(), nil::<i64>())
        }
    }
}

/// Each binder an inference variable; a region's and an effect's (C46)
/// kept apart from a type's.
pub fn instantiate_vars(s: &'static St, tvars: Strings, t: &'static Ty, regions: List<i64>, effects: List<i64>) -> &'static Inst {
    if null_p(tvars) {
        inst(t, s, regions, effects)
    } else {
        let tagcase_ = fresh(s);
        match *tagcase_ {
            Res::Res(m, es, s) => {
                let tagcase_ = m;
                match *tagcase_ {
                    Ty::TyMeta(k) => {
                        instantiate_vars(s, cdr(tvars), replace_var(car(tvars), m, t), if char_eq_p(string_ref_i64(car(tvars), 0i64), '\'') {
                            kayak_rt::heap_cons(k, regions)
                        } else {
                            regions
                        }, if char_eq_p(string_ref_i64(car(tvars), 0i64), '~') {
                            kayak_rt::heap_cons(k, effects)
                        } else {
                            effects
                        })
                    }
                    _ => {
                        let other = tagcase_;
                        inst(t, s, regions, effects)
                    }
                }
            }
        }
    }
}

// The names in scope
